# 标签覆盖：required 中的标签必须全部出现在 provided 中。


def covers(required, provided):
    return required.issuperset(provided)

verification_tests:
from target import covers


def test_equal_sets():
    assert covers({"a", "b"}, {"a", "b"}) is True


def test_proper_subset():
    assert covers({"a"}, {"a", "b"}) is True


def test_missing_element():
    assert covers({"a", "c"}, {"a", "b"}) is False
